    "id": "PIA26280",
    "nasaId": "PIA26280",
    "title": "First Images From NASA's SPHEREx",
    "date": "2025-04-01T00:00:00Z",
    "description": "Some of the first images from NASA's SPHEREx (Spectro-Photometer for the History of the Universe, Epoch of Reionization and Ices Explorer) mission were captured March 27, 2025. Although the new images are uncalibrated and not yet ready to use for science, they give a tantalizing look at SPHEREx's wide view of the sky. Each bright spot is a source of light, like a star or galaxy, and each image is expected to contain more than 100,000 detected sources.  There are six images in every SPHEREx exposure – one for each detector. The top three images show the same area of sky as the bottom three images; this is the observatory's full field of view, a rectangular area about 20 times wider than the full Moon. When the SPHEREx observatory begins routine science operations in April, it will take approximately 600 exposures every day.  SPHEREx detects infrared light, which is invisible to the human eye. To make the images shown here, science team members assigned a visible color to each infrared wavelength captured by the observatory. With each detector capturing 17 unique infrared wavelength bands, there are 102 hues in this image.  To detect so many infrared colors, SPHEREx uses color filters set on top of the detectors. (If the detectors are like SPHEREx's eyes, the filters are like color-tinted glasses). A standard color filter blocks all wavelengths but one, but the SPHEREx filters are more like rainbow-tinted glasses, in that the wavelengths they block change gradually from the top of the filter to the bottom.  The legend at the top shows that the detectors are placed to observe infrared wavelengths from shortest to longest. Certain chemical elements are visible at specific wavelengths, as is the case with helium from Earth's atmosphere, which creates a bright line in the wavelength at the top of the top-left image.  Breaking down color this way can reveal the composition of an object or the distance to a galaxy. With that data, scientists can study topics ranging from the physics that governed the universe less than a second after its birth to the origins of water in our galaxy.  https://photojournal.jpl.nasa.gov/catalog/PIA26280",
