    "description": "A SpaceX Falcon 9 rocket, carrying NASA’s SPHEREx (Spectro-Photometer for the History of the Universe, Epoch of Reionization and Ices Explorer) observatory and PUNCH (Polarimeter to Unify the Corona and Heliosphere) satellites, launches from Space Launch Complex 4 East at Vandenberg Space Force Base in California on Tuesday, March 11, 2025. SPHEREx will use its telescope to provide an all-sky spectral survey, creating a 3D map of the entire sky to help scientists investigate the origins of our universe. PUNCH will study origins of the Sun’s outflow of material, or the solar wind, capturing continuous 3D images of the Sun’s corona and the solar wind’s journey into the solar system. ",
