    "description": "NASA videographer Jacob Shaw and the video team from NASA’s Armstrong Flight Research Center in Edwards, California, prepare to film the launch of NASA’s SPHEREx mission at Vandenberg Space Force Base. The mission, short for Specto-Photometer for the History of the Universe, Epoch of Reionization, and Ices Explorer, launched on March 11, 2025, aboard a SpaceX Falcon 9 rocket, continuing NASA’s exploration of the cosmos – and its commitment to visual storytelling.",
