    "id": "PIA26542",
    "nasaId": "PIA26542",
    "title": "SPHEREx in Horizontal Orientation",
    "date": "2025-01-23T00:00:00Z",
    "description": "NASA's SPHEREx observatory is oriented in a horizontal position, revealing all three layers of photon shields as well as the telescope. This photo was taken at BAE Systems in Boulder, Colorado, in April 2024.  Short for Spectro-Photometer for the History of the Universe, Epoch of Reionization and Ices Explorer, SPHEREx will create a map of the cosmos like no other. Using a technique called spectroscopy to image the entire sky in 102 wavelengths of infrared light, SPHEREx will gather information about the composition of and distance to millions of galaxies and stars. With this map, scientists will study what happened in the first fraction of a second after the big bang, how galaxies formed and evolved, and the origins of water in planetary systems in our galaxy.  https://photojournal.jpl.nasa.gov/catalog/PIA26542",
    "plainEnglishSummary": "These cone-shaped aluminum shields act like three layered sun umbrellas, reflecting away blistering heat from the Sun and Earth so the telescope stays super cold.",
    "plainEnglishKeyTakeaway": "Because it detects heat light, the telescope must stay ice-cold (-350°F) so it doesn't blind itself with its own warmth.",
    "category": "Science & Cosmos",
    "thumbnailUrl": "https://images-assets.nasa.gov/image/PIA26542/PIA26542~medium.jpg",
    "fullImageUrl": "https://images-assets.nasa.gov/image/PIA26542/PIA26542~orig.jpg",
