    "id": "PIA26540",
    "nasaId": "PIA26540",
    "title": "SPHEREx Undergoes Acoustic Testing",
    "date": "2025-01-23T00:00:00Z",
    "description": "NASA's SPHEREx observatory is installed in the Fiesta Area at BAE Systems in Boulder, Colorado, in July 2024. The observatory is surrounded by speaker stacks used to perform acoustics testing, which subjects the spacecraft to the acoustics loads that it will experience during launch.  Short for Spectro-Photometer for the History of the Universe, Epoch of Reionization and Ices Explorer, SPHEREx will create a map of the cosmos like no other. Using a technique called spectroscopy to image the entire sky in 102 wavelengths of infrared light, SPHEREx will gather information about the composition of and distance to millions of galaxies and stars. With this map, scientists will study what happened in the first fraction of a second after the big bang, how galaxies formed and evolved, and the origins of water in planetary systems in our galaxy.  https://photojournal.jpl.nasa.gov/catalog/PIA26540",
    "plainEnglishSummary": "Before riding a rocket, the spacecraft was strapped to giant shake tables and blasted with eardrum-shattering sound to guarantee it could survive liftoff.",
    "plainEnglishKeyTakeaway": "Rocket blastoffs create violent vibrations. Rigorous ground testing ensures not a single screw or mirror gets knocked loose.",
