    "description": "Crews conduct additional solar array deployment testing for NASA’s PUNCH (Polarimeter to Unify the Corona and Heliosphere) satellites at Astrotech Space Operations located on Vandenberg Space Force Base in California on Wednesday, Jan. 22, 2025. PUNCH, consisting of four satellites, will produce continuous 3D images of the solar wind and solar storms as it travels from the Sun to Earth to better understand how material in the corona accelerates. PUNCH, along with NASA’s SPHEREx (Spectro-Photometer for the History of the Universe, Epoch of Reionization and Ices Explorer), a space telescope, will launch aboard a SpaceX Falcon 9 rocket from Launch Complex 4E at Vandenberg Space Force Base in Central California on Thursday, Feb. 27, 2025.",
