    "nasaId": "KSC-20250119-PH-ATR01_0476",
    "title": "PUNCH Satellites Lift to Work Stand fo Testing Operations",
    "date": "2025-01-19T00:00:00Z",
    "description": "Technicians conduct testing operations on NASA’s PUNCH (Polarimeter to Unify the Corona and Heliosphere) spacecraft onto a work stand for testing operations at the Astrotech Processing Facility on Vandenberg Space Force Base in California on Sunday, Jan. 19, 2025. PUNCH, consisting of four satellites, will produce continuous 3D images of the solar wind and solar storms as it travels from the Sun to Earth to better understand how material in the corona accelerates to become the solar wind that fills the solar system. PUNCH will launch aboard a SpaceX Falcon 9 rocket in late February 2025.",
    "plainEnglishSummary": "Technicians conduct testing operations on NASA’s PUNCH (Polarimeter to Unify the Corona and Heliosphere) spacecraft onto a work stand for testing operations at the Astrotech Processing Facility on Vandenberg Space Force Base in California on Sunday, Jan. 19, 2025.",
    "plainEnglishKeyTakeaway": "SPHEREx is surveying the entire cosmos across 102 infrared wavelengths to map 450 million galaxies and uncover water throughout space.",
    "category": "Testing & Prep",
    "thumbnailUrl": "https://images-assets.nasa.gov/image/KSC-20250119-PH-ATR01_0476/KSC-20250119-PH-ATR01_0476~medium.jpg",
