    "id": "KSC-20250114-PH-BMF01_0001",
    "nasaId": "KSC-20250114-PH-BMF01_0001",
    "title": "SPHEREx Spacecraft Arrival and Unboxing",
    "date": "2025-01-14T00:00:00Z",
    "description": "Employees with BAE Systems pose for a photo following the arrival of NASA’s SPHEREx (Spectro-Photometer for the History of the Universe, Epoch of Reionization and Ices Explorer) observatory inside the Astrotech Space Operations Facility at Vandenberg Space Force Base in California on Tuesday, Jan. 14, 2025. BAE Systems (formerly Ball Aerospace) built the telescope and the spacecraft bus. SPHEREx will use its telescope to provide an all-sky spectral survey, creating a 3D map of the entire sky to help scientists investigate the origins of our universe. Riding along with SPHEREx, NASA’s PUNCH (Polarimeter to Unify the Corona and Heliosphere) mission will study origins of the Sun’s outflow of material, or the solar wind. Liftoff aboard a SpaceX Falcon 9 rocket is targeted for 10:09 p.m. EST (7:09 p.m. PST), Thursday, Feb. 27, 2025, from Space Launch Complex 4 East.",
