    "id": "PIA25788",
    "nasaId": "PIA25788",
    "title": "SPHEREx Detector Filters",
    "date": "2023-11-09T00:00:00Z",
    "description": "NASA's SPHEREx mission will use these filters to conduct spectroscopy, a technique that lets scientists measure individual wavelengths of light from a source, which can reveal information such as the chemical composition of the object or how far away it is.  Each about the size of a cracker, the filters appear iridescent to the naked eye. The filters have multiple segments that block all but one specific wavelength of infrared light. Every object SPHEREx images will be observed by each segment, enabling scientists to see the specific infrared wavelengths emitted by every star or galaxy the telescope views. In total, SPHEREx can observe more than 100 distinct wavelengths.  Short for Specto-Photometer for the History of the Universe, Epoch of Reionization and Ices Explorer, SPHEREx will create a map of the cosmos like no other, imaging the entire sky and gathering information about millions of galaxies. With this map, scientists will study what happened in the first fraction of a second after the big bang, the history of galaxy evolution, and the origins of water in planetary systems in our galaxy.  https://photojournal.jpl.nasa.gov/catalog/PIA25788",
    "plainEnglishSummary": "NASA's SPHEREx mission will use these filters to conduct spectroscopy, a technique that lets scientists measure individual wavelengths of light from a source, which can reveal information such as the chemical composition of the object or how far away it is. Each about the size of a cracker, the filters appear iridescent to the naked eye.",
    "plainEnglishKeyTakeaway": "SPHEREx is surveying the entire cosmos across 102 infrared wavelengths to map 450 million galaxies and uncover water throughout space.",
    "category": "Science & Cosmos",
    "thumbnailUrl": "https://images-assets.nasa.gov/image/PIA25788/PIA25788~medium.jpg",
    "fullImageUrl": "https://images-assets.nasa.gov/image/PIA25788/PIA25788~orig.jpg",
    "origImageUrl": "https://images-assets.nasa.gov/image/PIA25788/PIA25788~medium.jpg",
    "center": "JPL",
