    "date": "2023-11-09T00:00:00Z",
    "description": "The telescope for NASA's SPHEREx mission undergoes testing at NASA's Jet Propulsion Laboratory in Southern California in September 2023. The telescope collects infrared light from distant sources using three mirrors and six detectors. It is tilted on its base so it can see as much of the sky as possible while remaining within the protection of the spacecraft's photon shields – three concentric cones that protect the telescope from light and heat from the Sun and Earth.  https://photojournal.jpl.nasa.gov/catalog/PIA25787",
